      ro: "O clădire monumentală din Piața Kasbah care combină arhitectura islamică tradițională cu facilități administrative moderne.",
      en: "A monumental building in the Kasbah Square that combines traditional Islamic architecture with modern administrative facilities.",
      es: "Un edificio monumental en la Plaza Kasbah que combina la arquitectura islámica tradicional con instalaciones administrativas modernas.",
      pt: "Um edifício monumental na Praça Kasbah que combina a arquitetura islâmica tradicional com instalações administrativas modernas.",
      fr: "Un bâtiment monumental sur la place de la Kasbah qui combine l'architecture islamique traditionnelle avec des installations administratives modernes.",
