      hu: ["A 17. században épült Sfax medinájában.", "1939 óta a Népművészeti és Hagyományőrző Múzeumnak ad otthont.", "Kétszintes épület tipikus központi belső udvarral.", "Az építészet és a díszítés andalúz hatásokat mutat.", "Ékszerek és népviseletek értékes gyűjteményének ad otthont.", "Az egykor befolyásos Jellouli család lakóháza volt."],
      ro: ["Construită în secolul al XVII-lea în medina din Sfax.", "Găzduiește Muzeul de Arte și Tradiții Populare din 1939.", "Clădire cu două etaje și o curte interioară centrală tipică.", "Prezintă influențe andaluze în arhitectură și decorațiuni.", "Adăpostește colecții valoroase de bijuterii și costume populare.", "Fosta reședință a influentei familii Jellouli."],
      en: ["Built in the 17th century in the Medina of Sfax.", "Home to the Museum of Popular Arts and Traditions since 1939.", "Two-story building with a typical central courtyard.", "Shows Andalusian influences in architecture and decoration.", "Houses valuable collections of jewelry and folk costumes.", "Former residence of the influential Jellouli family."],
      es: ["La casa fue construida en 1750 para la familia Jellouli.", "El patio tiene un diámetro de 10 metros.", "Los arabescos de la fachada cubren 50 metros cuadrados.", "El museo se inauguró en 1960 y cuenta con 8 salas.", "La colección incluye más de 1.000 objetos.", "El edificio fue restaurado a fondo en 1995."],
