      fr: ["La maison fut construite en 1750 pour la famille Jellouli.", "La cour a un diamètre de 10 mètres.", "Les arabesques de la façade couvrent 50 mètres carrés.", "Le musée fut inauguré en 1960 et compte 8 salles.", "La collection comprend plus de 1 000 objets.", "Le bâtiment fut entièrement restauré en 1995."],
